        integer file_mantra;
        initial begin
          file_mantra = $fopen("output.txt");//added
          $fwrite(file_mantra, "time, ");
      $fwrite(file_mantra, "ins,");
      $fwrite(file_mantra, "ad1,");
      $fwrite(file_mantra, "ad2,");

          $fwrite(file_mantra, "\n");//added
          forever begin
            #1
            $fwrite(file_mantra, "%0d, ", $time);
        $fwrite(file_mantra, "%h, ", ins);
        $fwrite(file_mantra, "%h, ", ad1);
        $fwrite(file_mantra, "%h, ", ad2);

            $fwrite(file_mantra, "\n");
          end
        end





// ============================================
// === LLM Enhanced Stimuli (Phase 1) ===
initial begin
    // [Auto-Moved Vars]
        integer i;

    // 1. DECLARE VARIABLES FIRST (Top of block)


    // 2. THEN WAIT for original tests
    wait(llm_go_signal == 1);

    // 3. THEN execute logic
    $display("LLM: Starting Mutation Testing Stimuli...");

    // Initialize Inputs
    rst = 0;
    fetch = 2'b00;
    data = 8'h00;

    // Hold Reset for initialization
    #20;
    rst = 1;
    #10;

    // ------------------------------------------------------------
    // TEST CASE 1: Fetch 01 (Load ins_p1) - Boundary & Bit Patterns
    // ------------------------------------------------------------
    // Target: Verify 'ins' (bits 7:5) and 'ad1' (bits 4:0) logic
    fetch = 2'b01;

    // Pattern: All Zeros
    data = 8'h00;
    #10;

    // Pattern: All Ones (Checks max values for ins and ad1)
    data = 8'hFF;
    #10;

    // Pattern: Boundary Check - Bit 5 (LSB of ins)
    // 8'h20 = 0010_0000 -> Expected: ins=1, ad1=0
    data = 8'h20;
    #10;

    // Pattern: Boundary Check - Bit 4 (MSB of ad1)
    // 8'h10 = 0001_0000 -> Expected: ins=0, ad1=16
    data = 8'h10;
    #10;

    // Pattern: Alternating Bits (0xAA = 10101010)
    data = 8'hAA;
    #10;

    // Pattern: Alternating Bits (0x55 = 01010101)
    data = 8'h55;
    #10;

    // Walking 1s on ins_p1 to verify every bit connection and slice boundaries
    for (i = 0; i < 8; i = i + 1) begin
        data = 1 << i;
        #10;
    end

    // ------------------------------------------------------------
    // TEST CASE 2: Fetch 10 (Load ins_p2) - Independence Check
    // ------------------------------------------------------------
    // Target: Verify 'ad2' updates and 'ins/ad1' hold their values
    fetch = 2'b10;

    // Load ins_p2 with Walking 1s
    for (i = 0; i < 8; i = i + 1) begin
        data = 1 << i;
        #10;
    end

    // Load ins_p2 with 0xFF
    data = 8'hFF;
    #10;

    // ------------------------------------------------------------
    // TEST CASE 3: Fetch 00 & 11 (Hold State)
    // ------------------------------------------------------------
    // Change data, but fetch is 00 -> Should Hold previous values
    fetch = 2'b00;
    data = 8'h00;
    #10;

    data = 8'hAA;
    #10;

    // Change data, but fetch is 11 -> Should Hold previous values
    fetch = 2'b11;
    data = 8'h55;
    #10;

    // ------------------------------------------------------------
    // TEST CASE 4: Reset Dominance
    // ------------------------------------------------------------
    // Assert reset while trying to write to registers
    fetch = 2'b01;
    data = 8'hFF;
    #5;
    rst = 0; // Active Low Reset
    #10;
    // Release Reset
    rst = 1;
    #10;

    // ------------------------------------------------------------
    // TEST CASE 5: Rapid Switching (Control Flow)
    // ------------------------------------------------------------
    // Write p1
    fetch = 2'b01;
    data = 8'hF0;
    #10;

    // Write p2
    fetch = 2'b10;
    data = 8'h0F;
    #10;

    // Write p1 again
    fetch = 2'b01;
    data = 8'hCC;
    #10;

    // 4. Cleanup
    $display("LLM: Tests Finished. Handing over to Original TB...");
    llm_go_signal = 0;
end
// ============================================


// === Global Watchdog ===

// === Global Safety Watchdog (Injected) ===
initial begin
    #200000;
    $display("\n[Watchdog] Timeout triggered at %t!", $time);
    if (file_mantra != 0) $fclose(file_mantra);
    $finish;
end

endmodule

